[Due to length, this would include:
1. Collector script in Python/Node that hooks into Claude Code
2. PostgreSQL schema with tables for requests, tokens, costs, quality_metrics
3. Express API with endpoints like GET /api/metrics/usage, GET /api/metrics/costs, etc.
4. React components: UsageChart.tsx, CostBreakdown.tsx, QualityMetrics.tsx
5. Alert system using Slack webhooks
6. Screenshot showing: line chart of daily requests, pie chart of costs by model, table of top users, alerts panel]

# Example structure provided to show expectations:

```typescript
// Backend: src/metrics/collector.ts
import { PrismaClient } from '@prisma/client';
import { ClaudeCodeHook } from './hooks';

const prisma = new PrismaClient();

export class MetricsCollector {
  async captureRequest(data: {
    userId: string;
    model: string;
    inputTokens: number;
    outputTokens: number;
    latencyMs: number;
    success: boolean;
    cost: number;
  }) {
    await prisma.claudeRequest.create({ data });

    // Check alerts
    await this.checkThresholds(data.userId);
  }

  async checkThresholds(userId: string) {
    const today = new Date();
    const monthStart = new Date(today.getFullYear(), today.getMonth(), 1);

    const monthlyCost = await prisma.claudeRequest.aggregate({
      where: {
        userId,
        createdAt: { gte: monthStart }
      },
      _sum: { cost: true }
    });

    const user = await prisma.user.findUnique({ where: { id: userId } });

    if (monthlyCost._sum.cost! > user!.costBudget) {
      await this.sendAlert({
        type: 'budget_exceeded',
        userId,
        message: `User ${user!.name} exceeded monthly budget: $${monthlyCost._sum.cost} / $${user!.costBudget}`
      });
    }
  }
}

// Frontend: src/components/Dashboard/UsageChart.tsx
import { LineChart, Line, XAxis, YAxis, Tooltip, Legend } from 'recharts';
import { useQuery } from '@tanstack/react-query';

export function UsageChart() {
  const { data } = useQuery(['usage'], () =>
    fetch('/api/metrics/usage?days=30').then(r => r.json())
  );

  return (
    <div className="chart-container">
      <h2>Usage Trends (30 days)</h2>
      <LineChart width={800} height={400} data={data}>
        <XAxis dataKey="date" />
        <YAxis />
        <Tooltip />
        <Legend />
        <Line type="monotone" dataKey="requests" stroke="#8884d8" name="Requests" />
        <Line type="monotone" dataKey="tokens" stroke="#82ca9d" name="Tokens (K)" />
      </LineChart>
    </div>
  );
}
